CREATE TABLE IF NOT EXISTS workspace_roles (org_id BIGINT NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(100) NOT NULL,permissions_json JSON NOT NULL,system_role BOOLEAN NOT NULL DEFAULT 0,PRIMARY KEY(org_id,code));
CREATE TABLE IF NOT EXISTS user_workspace_roles (org_id BIGINT NOT NULL,user_id BIGINT NOT NULL,role_code VARCHAR(50) NOT NULL,PRIMARY KEY(org_id,user_id,role_code),FOREIGN KEY(org_id,role_code) REFERENCES workspace_roles(org_id,code));
CREATE TABLE IF NOT EXISTS user_permission_overrides (org_id BIGINT NOT NULL,user_id BIGINT NOT NULL,permission VARCHAR(80) NOT NULL,allowed BOOLEAN NOT NULL,PRIMARY KEY(org_id,user_id,permission));
CREATE TABLE IF NOT EXISTS workspace_statuses (org_id BIGINT NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(100) NOT NULL,color VARCHAR(7) NOT NULL,category VARCHAR(20) NOT NULL,sort_order INT NOT NULL DEFAULT 0,active BOOLEAN NOT NULL DEFAULT 1,PRIMARY KEY(org_id,code));
CREATE TABLE IF NOT EXISTS workspace_event_outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id CHAR(36) NOT NULL UNIQUE,org_id BIGINT NOT NULL,event_type VARCHAR(50) NOT NULL,user_id BIGINT NOT NULL DEFAULT 0,published_at TIMESTAMP(6) NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX ix_workspace_events(published_at,id));
